let o=$json.output;if(typeof o==='string')o=JSON.parse(o.trim().replace(/^```(?:json)?\s*|\s*```$/g,''));
const c=$('Full Brief Context').first().json;
if(!c||!c.production||!c.weather||!c.full_template||!Array.isArray(c.slot_keys))throw Error('Missing measured template context');
if(!o||typeof o!=='object'||Array.isArray(o)||Object.keys(o).length!==c.slot_keys.length)throw Error('Invalid AI slot schema');
for(const k of c.slot_keys){const v=o[k];if(typeof v!=='string'||!v.trim()||v.length>110||/[\r\n{}\[\]<>\d%$]/.test(v)||/AI_|https?:|guarantee|\b(?:online|offline|healthy|loaded|operational)\b/i.test(v))throw Error('Unsafe commentary slot '+k);}
const fields={...o,greeting:c.greeting,weather_line:c.weather_line,production_lines:c.production_lines,history_line:c.history_line};
const b=c.full_template.replace(/\{([A-Za-z_]+)\}/g,(_,k)=>{if(typeof fields[k]!=='string')throw Error('Unresolved slot '+k);return fields[k].trim();});
if(/\{[^}]*\}|AI_[A-Z_]+/.test(b)||(b.match(/\[\[LIVE_CORE_STATUS\]\]/g)||[]).length!==1)throw Error('Unresolved template');
if(b.length>2900)throw Error('Full template too long for late telemetry and speech');
return [{json:{prepared_brief:b,ai_slots:o,source_context:c}}];
